import{_ as a,o as t,c as n,a2 as r}from"./chunks/framework.xeBd2WE1.js";const m=JSON.parse('{"title":"AI 动态 · 2026-09-07","description":"","frontmatter":{"title":"AI 动态 · 2026-09-07","date":"2026-09-07T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-09/ai-news-2026-09-07.md","filePath":"news/2026-09/ai-news-2026-09-07.md","lastUpdated":null}'),s={name:"news/2026-09/ai-news-2026-09-07.md"};function o(i,e,c,p,l,h){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-动态-·-2026-09-07" tabindex="-1">AI 动态 · 2026-09-07 <a class="header-anchor" href="#ai-动态-·-2026-09-07" aria-label="Permalink to &quot;AI 动态 · 2026-09-07&quot;">​</a></h1><blockquote><p>截至 2026-09-07。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="作者抗议-出版商与经纪公司争夺anthropic和解金份额" tabindex="-1">作者抗议：出版商与经纪公司争夺Anthropic和解金份额 <a class="header-anchor" href="#作者抗议-出版商与经纪公司争夺anthropic和解金份额" aria-label="Permalink to &quot;作者抗议：出版商与经纪公司争夺Anthropic和解金份额&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-09-07">2026-09-07</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/2f3201ee0a2e.jpg" alt="配图"></p><p>在Anthropic与作者的和解案中，出版商和经纪公司被指试图索取超出合理范围的赔偿份额，引发作者群体不满。此案涉及AI训练数据版权纠纷的后续分配问题，凸显了AI内容使用中利益分配的复杂性。对读者：关注AI版权案例的后续发展，了解内容创作者在AI时代的权益博弈。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/09/06/authors-push-back-as-publishers-and-agents-seek-share-of-anthropic-settlement/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="travis-kalanick的atoms或进军robotaxi业务" tabindex="-1">Travis Kalanick的Atoms或进军Robotaxi业务 <a class="header-anchor" href="#travis-kalanick的atoms或进军robotaxi业务" aria-label="Permalink to &quot;Travis Kalanick的Atoms或进军Robotaxi业务&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-09-07">2026-09-07</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/7fb9c1616b6c.jpg" alt="配图"></p><p>Uber创始人Travis Kalanick旗下公司Atoms近期获17亿美元融资，由Andreessen Horowitz领投，可能涉足Robotaxi领域。Kalanick曾表示Atoms将助其完成“未竟事业”，此举或加剧自动驾驶出行市场竞争。对读者：关注Atoms后续动向，评估其对出行行业格局的潜在影响。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/09/06/travis-kalanicks-atoms-might-be-getting-into-the-robotaxi-business/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="微软公布project-zenith计划-优化开发者pc" tabindex="-1">微软公布Project Zenith计划，优化开发者PC <a class="header-anchor" href="#微软公布project-zenith计划-优化开发者pc" aria-label="Permalink to &quot;微软公布Project Zenith计划，优化开发者PC&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">少数派</span><time datetime="2026-09-07">2026-09-07</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/5e293c9b6b32.webp" alt="配图"></p><p>微软推出Project Zenith，面向高性能开发者设备，预配置开发工具、调整系统设置，并强化本地AI功能，要求至少64GB统一内存和250GB/s带宽，以运行300亿参数以上大模型。首批设备采用AMD Ryzen AI Halo平台。对读者：开发者可关注此配置，提升本地AI开发效率。</p><p class="news-entry-source"><a href="https://sspai.com/post/114250" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="英伟达129亿美元收购hugging-face-引发中立性担忧" tabindex="-1">英伟达129亿美元收购Hugging Face，引发中立性担忧 <a class="header-anchor" href="#英伟达129亿美元收购hugging-face-引发中立性担忧" aria-label="Permalink to &quot;英伟达129亿美元收购Hugging Face，引发中立性担忧&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-09-07">2026-09-07</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/b2bb2f3c454f.png" alt="配图"></p><p>英伟达宣布以129亿美元收购Hugging Face，交易预计2027年上半年完成。此举引发对Hugging Face中立性的担忧，被视为AI领域最具反垄断审查价值的并购之一。对读者：开源平台用户应关注收购后平台政策变化。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/5dtlrdsBbSIZfWUUF6JD?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="西雅图时报与newsday起诉openai和微软侵犯版权" tabindex="-1">西雅图时报与Newsday起诉OpenAI和微软侵犯版权 <a class="header-anchor" href="#西雅图时报与newsday起诉openai和微软侵犯版权" aria-label="Permalink to &quot;西雅图时报与Newsday起诉OpenAI和微软侵犯版权&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-09-07">2026-09-07</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/128cbb57d494.jpg" alt="配图"></p><p>《西雅图时报》和《Newsday》起诉OpenAI和微软，指控其未经许可使用新闻报道训练AI模型，并要求销毁相关模型。这是媒体机构对AI公司的最新法律行动，反映内容创作者与AI巨头之间的紧张关系。对读者：留意AI版权诉讼进展，思考内容使用边界。</p><p class="news-entry-source"><a href="https://www.theverge.com/ai-artificial-intelligence/990932/seattle-times-newsday-lawsuit-openai-microsoft" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="exaone发布金融时间序列基础模型" tabindex="-1">EXAONE发布金融时间序列基础模型 <a class="header-anchor" href="#exaone发布金融时间序列基础模型" aria-label="Permalink to &quot;EXAONE发布金融时间序列基础模型&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">arXiv cs.AI</span><time datetime="2026-09-07">2026-09-07</time></p><p>EXAONE Forecast for Finance是专为金融预测设计的时间序列基础模型，针对金融数据动态进行优化，克服通用模型在金融领域的局限。该模型有望提升金融预测的准确性和效率。对读者：金融从业者可关注该模型在量化分析中的应用潜力。</p><p class="news-entry-source"><a href="https://arxiv.org/abs/2609.04239" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="harbor-adapters-大规模agent评测基础设施" tabindex="-1">Harbor Adapters：大规模Agent评测基础设施 <a class="header-anchor" href="#harbor-adapters-大规模agent评测基础设施" aria-label="Permalink to &quot;Harbor Adapters：大规模Agent评测基础设施&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">arXiv cs.AI</span><time datetime="2026-09-07">2026-09-07</time></p><p>Harbor Adapters提供统一评测基础设施，将80多个Agent基准适配至任意Agent，并对8个模型在54个基准上进行大规模评估。该工作有助于标准化Agent能力评测，推动Agent技术发展。对读者：Agent开发者可利用该基础设施进行模型选型。</p><p class="news-entry-source"><a href="https://arxiv.org/abs/2609.04298" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="iris-新型搜索agent训练方法" tabindex="-1">Iris：新型搜索Agent训练方法 <a class="header-anchor" href="#iris-新型搜索agent训练方法" aria-label="Permalink to &quot;Iris：新型搜索Agent训练方法&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">arXiv cs.AI</span><time datetime="2026-09-07">2026-09-07</time></p><p>Iris-mini和Iris-pro是两种搜索Agent，通过从网页超链接结构反向构造多跳任务进行训练，提升搜索能力。该方法有望增强AI在复杂信息检索中的表现。对读者：关注搜索Agent技术进展，或影响未来搜索引擎形态。</p><p class="news-entry-source"><a href="https://arxiv.org/abs/2609.04304" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="微软开源markitdown-文件转markdown工具" tabindex="-1">微软开源MarkItDown：文件转Markdown工具 <a class="header-anchor" href="#微软开源markitdown-文件转markdown工具" aria-label="Permalink to &quot;微软开源MarkItDown：文件转Markdown工具&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">microsoft/markitdown</span><time datetime="2026-09-07">2026-09-07</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/dc527078178e.png" alt="配图"></p><p>微软开源MarkItDown，一个Python工具，可将多种文件和Office文档转换为Markdown格式，便于AI处理。该工具支持多种文件类型，有助于数据预处理和文档管理。对读者：开发者可集成此工具，简化文档转换流程。</p><p class="news-entry-source"><a href="https://github.com/microsoft/markitdown" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><p>（本日无新条目）</p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><p>（本日无新条目）</p></div>',8)])])}const g=a(s,[["render",o]]);export{m as __pageData,g as default};
